package com.bank.multidc;

import java.util.*;
import java.util.logging.*;

public class MultiDcReplicationDemo {
    private static final Logger log = Logger.getLogger(MultiDcReplicationDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Home region per account (active-active with write ownership).
        Map<String, String> homeRegion = Map.of("SAV2001", "mumbai", "CUR3001", "chennai");
        ReplicationPlanner planner = new ReplicationPlanner(homeRegion);

        // RPO (recovery point objective) ≈ replication lag.
        long rpoMs = planner.recoveryPointObjectiveMs(1500);   // 1.5s mirror lag
        log.info(() -> "Estimated RPO (possible data loss window) = " + rpoMs + " ms");

        // Offset translation on failover: Mumbai offset 42 → Chennai offset.
        Map<Long, Long> checkpoint = Map.of(40L, 980L, 41L, 981L, 42L, 982L);
        long chennaiOffset = planner.translateOffset(42L, checkpoint);
        log.info(() -> "After failover, resume at Chennai offset " + chennaiOffset);

        // Active-active write-ownership guard: Rajesh may only write in his home region.
        checkWrite(planner, "SAV2001", "mumbai");   // allowed
        checkWrite(planner, "SAV2001", "chennai");  // rejected (not home)
        checkWrite(planner, "CUR3001", "chennai");  // allowed
    }

    private static void checkWrite(ReplicationPlanner planner, String account, String region) {
        if (planner.canWrite(account, region))
            log.info(() -> "WRITE allowed: " + account + " in " + region);
        else
            log.warning(() -> "WRITE rejected: " + account + " not owned by " + region
                    + " (route to home region to avoid conflicts)");
    }
}

