class ReplicationPlanner {
    private final Map<String, String> homeRegion;
    ReplicationPlanner(Map<String, String> homeRegion) {
        this.homeRegion = Map.copyOf(homeRegion);
    }

    // RPO is roughly the replication lag: anything newer may be lost in a sudden outage.
    long recoveryPointObjectiveMs(long replicationLagMs) {
        if (replicationLagMs < 0) throw new IllegalArgumentException("lag must be >= 0");
        return replicationLagMs;
    }

    // Map a source-cluster offset to the target-cluster offset via the checkpoint map.
    long translateOffset(long sourceOffset, Map<Long, Long> checkpoint) {
        Long target = checkpoint.get(sourceOffset);
        if (target == null) throw new NoSuchElementException(
            "No checkpoint for source offset " + sourceOffset + " — cannot translate safely");
        return target;
    }

    // Active-active with write ownership: a key may only be written in its home region.
    boolean canWrite(String account, String region) {
        return region.equals(homeRegion.get(account));
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
